import sys

def is_square_string(s):
    n = len(s)
    if n % 2 != 0:
        return False
    half = n // 2
    return s[:half] == s[half:]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        s = data[index]
        index += 1
        if is_square_string(s):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
